def base(x, j, p):
    (a, b) = p
    if j == 0:
        return x
    if j == 1:
        return x / (1 + a * abs(x) ** b)
    if j == 2:
        return x * (1 - np.exp(-a * abs(x) ** b))
    if j == 3:
        return np.sign(x) * abs(x) ** b
    if j == 4:
        return x / (1 + a * abs(x) ** b) ** 0.5
    if j == 5:
        return x + a * np.sign(x) * abs(x) ** b
    if j == 6:
        return np.tanh(a * x)
    if j == 7:
        return np.arctan(a * x)

def robust(h, v):
    k = np.ones(len(v), bool)
    for _ in range(7):
        if h.ndim == 2:
            c = fit(h[k], v[k])
            pred = h @ c
        else:
            c = fit(h[k].reshape(-1, h.shape[-1]), v[k].ravel())
            pred = h @ c
        e = np.linalg.norm(pred - v, axis=1)
        new = e <= max(4 * np.median(e), 0.001)
        if np.array_equal(new, k):
            break
        k = new
    return (np.sqrt(np.mean(e[k] ** 2) / 4), c, k)
